// Kəşfiyyat lentləri testi: node tools/intel-test.mjs [threatfeed faylı]
import { readFileSync, existsSync } from "node:fs";
import { parseBlacklistFeed } from "../src/store.js";
import { analyze } from "../src/analyze.js";

let fails = 0;
const ok = (c, name, extra = "") => { if (!c) { fails++; console.log("FAIL", name, extra); } };

const sample = [
  "# This hosts file was automatically generated by blacklist.gov.az",
  "",
  "azerpost.870189.com\r",
  "WWW.Azerpost-Track.cc",
  "skinsmonkey.com?referrer=pid%3D1",
  "facebook.com%2f@appeal-case.about-help.com",
  "0.0.0.0 asanpay-az.lat",
  "localhost",
].join("\n");
const hosts = parseBlacklistFeed(sample);
ok(hosts.includes("azerpost.870189.com"), "plain host kept");
ok(hosts.includes("azerpost-track.cc"), "www stripped + lowercased", JSON.stringify(hosts));
ok(hosts.includes("asanpay-az.lat"), "hosts-file format");
ok(!hosts.some((h) => h.includes("skinsmonkey") || h.includes("%") || h === "localhost"), "urls / garbage skipped", JSON.stringify(hosts));

const feedPath = process.argv[2];
if (feedPath && existsSync(feedPath)) {
  const all = parseBlacklistFeed(readFileSync(feedPath, "utf8"));
  console.log("real feed hosts:", all.length);
  ok(all.length > 5000, "real feed parsed");
}

// Mənbəyə görə səbəb mətni
const lookup = async (list) => new Map(list.filter((h) => h === "azerpost.870189.com").map((h) => [h, "blacklist_gov_az"]));
const r = await analyze("Bağlamanız saxlanılıb: https://azerpost.870189.com/az", { intelLookup: lookup, useLlm: false });
ok(r.flags.includes("intel_hit"), "intel_hit flag");
ok(r.reasons.some((x) => /dövlətin qara siyahısındadır \(Blacklist\.gov\.az\)/.test(x.text)) || r.urls[0].findings.some((f) => /Blacklist\.gov\.az/.test(f.text)), "blacklist reason text", JSON.stringify(r.reasons));
const r2 = await analyze("Bağlamanız saxlanılıb: https://www.azerpost.870189.com/az", { intelLookup: lookup, useLlm: false });
ok(r2.flags.includes("intel_hit"), "www. variant matched");
const r3 = await analyze("Bağlamanız saxlanılıb: https://azerpost.870189.com/az", { intelLookup: async () => new Set(["azerpost.870189.com"]), useLlm: false });
ok(r3.flags.includes("intel_hit"), "old Set-based lookup still works");

// Ümumi platformalar lentdən atılır və heç vaxt "qara siyahı" sayılmır
const plat = parseBlacklistFeed("google.com\ndocs.google.com\nsites.google.com\nbit.ly\ntinyurl.com\nxyz.vercel.app\nvercel.app\nkapitalbank.az\nazerpost.870189.com\n");
ok(plat.join() === "xyz.vercel.app,azerpost.870189.com", "platforms dropped", JSON.stringify(plat));
const everything = async (list) => new Map(list.map((h) => [h, "blacklist_gov_az"]));
const rg = await analyze("Məktəb sorğusu: https://docs.google.com/forms/d/e/abc/viewform", { intelLookup: everything, useLlm: false });
ok(!rg.flags.includes("intel_hit") && rg.score < 50, "google form not blacklisted", rg.score + " " + rg.flags);
const rb = await analyze("Endirim kampaniyası: https://bit.ly/3abcd", { intelLookup: everything, useLlm: false });
ok(!rb.flags.includes("intel_hit"), "bit.ly not blacklisted", rb.flags.join());
// IP link: domen "3.4" deyil
const ri = await analyze("Ödəniş üçün: http://185.12.3.4/k", { useLlm: false });
ok(ri.urls[0].reg === "185.12.3.4", "ip registrable", ri.urls[0].reg);
// Kampaniya domeni: sübutu olan link seçilir; təmiz saytın adı ictimai lentə düşmür
const rc = await analyze("Azərpoçt: bağlamanız saxlanılıb, ünvanı yeniləyin https://www.temiz-magaza.az/ və ya https://azerpost-x.top/pay", { useLlm: false, intelLookup: async () => new Map([["azerpost-x.top", "openphish"]]) });
ok(rc.campaign?.domain === "azerpost-x.top" && rc.campaign.evidence === true, "campaign evidence domain", JSON.stringify(rc.campaign));
const rn = await analyze("Azərpoçt: bağlamanız saxlanılıb, ünvanı yeniləyin https://www.temiz-magaza.az/", { useLlm: false });
ok(!rn.campaign || rn.campaign.evidence === false, "no evidence → domain not public", JSON.stringify(rn.campaign));
// Mesajdakı +995 nömrə bayraq qaldırır
const rp = await analyze("Kapital Bank əməkdaşıyam, kartınız bloklanır, WhatsApp-a yazın: +995 55 000 12 34", { useLlm: false });
ok(rp.flags.includes("phone_lookalike") && rp.urls.length === 0, "phone_lookalike flag", rp.flags.join());
// Artıq qara siyahıda olan link: blacklisted = true
ok(r.urls[0].blacklisted === true, "blacklisted field");

console.log(fails ? `intel-test: ${fails} xəta` : "intel-test: hamısı keçdi");
process.exit(fails ? 1 : 0);
